<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRoute,RouterLink} from 'vue-router';import {api,idr} from '../api';import type {Product} from '../stores';import {useCart,useSession} from '../stores';const route=useRoute(),product=ref<Product|null>(null),qty=ref(1),error=ref(''),cart=useCart(),session=useSession();onMounted(async()=>{try{product.value=await api(`/products/${route.params.slug}`)}catch(e:any){error.value=e.message}});async function add(){if(!session.user)return location.assign('/login');try{await cart.add(product.value!.id,qty.value)}catch(e:any){error.value=e.message}}</script>
<template><main class="container page"><RouterLink to="/products" class="back">← Back to catalog</RouterLink><p v-if="error" class="notice">{{error}}</p><section v-if="product" class="detail"><div class="detail-image"><img :src="product.images[0]?.imageUrl" :alt="product.name"/></div><div><small>{{product.category.name}} · {{product.sku}}</small><h1>{{product.name}}</h1><h2>{{idr(product.price)}}</h2><p>{{product.description}}</p><p :class="product.stock?'stock':'out'">{{product.stock?`${product.stock} available`:'Currently sold out'}}</p><div class="buy"><input v-model.number="qty" type="number" min="1" :max="product.stock"/><button class="button" :disabled="!product.stock" @click="add">Add to bag</button></div><ul><li>Complimentary shipping over Rp 1.500.000</li><li>Easy 14-day returns</li></ul></div></section></main></template>
